args.old_string:
import { Suspense } from 'react'
import { getProjectDetails, getProjectTitle } from '@/lib/data'

export default function ProjectPage({ params }: PageProps<'/projects/[slug]'>) {
  return (
    <Suspense fallback={<h1>Loading project...</h1>}>
      <Project params={params} />
    </Suspense>
  )
}

async function Project({
  params,
}: Pick<PageProps<'/projects/[slug]'>, 'params'>) {
  const { slug } = await params
  const [title, details] = await Promise.all([
    getProjectTitle(slug),
    getProjectDetails(slug),
  ])

  return (
    <main>
      <h1>{title}</h1>
      <p>{details.description}</p>
      <h2>Recent activity</h2>
      <ul>
        {details.activity.map((item) => (
          <li key={item}>{item}</li>
        ))}
      </ul>
    </main>
  )
}

args.new_string:
import { Suspense } from 'react'
import { navigation } from 'next/cache'
import { getProjectDetails, getProjectTitle } from '@/lib/data'

export const prefetch = 'partial'

type ProjectParams = Pick<PageProps<'/projects/[slug]'>, 'params'>

export default function ProjectPage({ params }: ProjectParams) {
  return (
    <main>
      <Suspense fallback={<h1>Loading project...</h1>}>
        <ProjectTitle params={params} />
      </Suspense>
      <Suspense fallback={<p>Loading project details...</p>}>
        <ProjectDetails params={params} />
      </Suspense>
    </main>
  )
}

async function ProjectTitle({ params }: ProjectParams) {
  const { slug } = await params
  return <h1>{await getProjectTitle(slug)}</h1>
}

async function ProjectDetails({ params }: ProjectParams) {
  await navigation()
  const { slug } = await params
  const details = await getProjectDetails(slug)

  return (
    <>
      <p>{details.description}</p>
      <h2>Recent activity</h2>
      <ul>
        {details.activity.map((item) => (
          <li key={item}>{item}</li>
        ))}
      </ul>
    </>
  )
}

