args.command:
node --input-type=module <<'JS'
const url = 'http://localhost:3417/projects/acme'
const state = encodeURIComponent(JSON.stringify(['', { children: ['__PAGE__', {}] }]))
for (const [kind, headers] of Object.entries({
  routeTree: { RSC: '1', 'Next-Router-Prefetch': '1', 'Next-Router-Segment-Prefetch': '/_tree' },
  pageShell: { RSC: '1', 'Next-Router-Prefetch': '1', 'Next-Router-Segment-Prefetch': '/projects/$d$slug/__PAGE__' },
  perLink: { RSC: '1', 'Next-Router-State-Tree': state, 'Next-Router-Prefetch': '2' },
  navigation: { RSC: '1', 'Next-Router-State-Tree': state },
})) {
  const response = await fetch(url, { headers })
  const body = await response.text()
  console.log(kind, response.status, body.length, {
    title: body.includes('Acme Storefront'),
    description: body.includes('Commerce storefront and checkout.'),
    detailsFallback: body.includes('Loading project details...'),
  })
}
JS

