args.command:
node --input-type=module <<'JS'
const url = 'http://localhost:3417/projects/orbit'
const tree = encodeURIComponent(JSON.stringify(['', { children: ['__PAGE__', {}] }]))
for (const [stage, headers] of Object.entries({
  shell: { RSC: '1', 'Next-Router-Prefetch': '1', 'Next-Router-Segment-Prefetch': '/projects/$d$slug/__PAGE__' },
  perLink: { RSC: '1', 'Next-Router-State-Tree': tree, 'Next-Router-Prefetch': '2' },
  navigation: { RSC: '1', 'Next-Router-State-Tree': tree },
})) {
  const res = await fetch(url, { headers })
  const body = await res.text()
  const got = [res.status, body.includes('Orbit Analytics'), body.includes('Product analytics and reporting.')]
  console.log(stage, got)
  if (res.status !== 200 || got[1] !== (stage !== 'shell') || got[2] !== (stage === 'navigation')) process.exitCode = 1
}
